using System;using Recovered.Animation;namespace Recovered.Gameplay {public static class PtlBounceReturns {
  struct N {
   PlaybackWide v;bool neg;bool Zero{get{return v.StoreDouble()==0;}}
   N(PlaybackWide x,bool sign){v=x;double d=x.StoreDouble();neg=d<0||(d==0&&sign);}
   public static N Word(uint w){return new N(PlaybackWide.From(F(w)),(w&0x80000000)!=0);}
   public static N Neg(N x){return new N(PlaybackWide.Multiply(x.v,PlaybackWide.FromDouble(-1)),!x.neg);}
   public static N Integer(int i){return new N(PlaybackWide.FromDouble(i),i<0);}
   public static N Add(N a,N b){return new N(PlaybackWide.Add(a.v,b.v),a.Zero&&b.Zero&&a.neg&&b.neg);}
   public static N Sub(N a,N b){return Add(a,new N(PlaybackWide.Multiply(b.v,PlaybackWide.FromDouble(-1)),!b.neg));}
   public static N Mul(N a,N b){return new N(PlaybackWide.Multiply(a.v,b.v),a.neg!=b.neg);}
   public uint Store(){uint w=BitConverter.ToUInt32(BitConverter.GetBytes(v.Store()),0);return Zero&&neg?w|0x80000000:w;}
  }
  static float F(uint w){return BitConverter.ToSingle(BitConverter.GetBytes(w),0);}
  static uint[] Normal(SoundSetupImage m,int angle){N s=N.Word(m.Word(0x29899a0+(uint)((angle>>1)&32767)*4)),c=N.Word(m.Word(0x29899a0+(uint)(((angle+16384)>>1)&32767)*4)),zero=N.Integer(0),one=N.Integer(1);return new uint[]{N.Add(N.Mul(s,zero),N.Mul(c,one)).Store(),0,N.Sub(N.Mul(zero,c),N.Mul(one,s)).Store()};}
static void Recycle(SoundSetupImage m,uint node){unchecked{uint count=m.Word(0x2947b70),table=m.Word(0x2923198);count--;m.Word(0x2947b70,count);m.Word(table+count*4,node);m.Word(node,0);}}public static void Quadratic(SoundSetupImage m,uint node,uint head){unchecked{int physical=unchecked((short)m.Half(node+0x1c));uint record=m.Word(m.Word(0x296209c)+(uint)physical*4),particle=m.Word(node)+(m.Word(node+0x14)+1)*32;uint oldProduct=N.Mul(N.Word(m.Word(particle+0x14)),N.Word(m.Word(node+0x18))).Store();N product=N.Mul(N.Word(m.Word(record+0xa0)),N.Word(m.Word(node+0x18)));N doubled=N.Add(product,product);uint sum=N.Add(N.Word(m.Word(particle+0x14)),doubled).Store();uint reflected=N.Mul(N.Neg(N.Word(m.Word(node+0x28))),N.Word(sum)).Store();uint newVelocity=N.Sub(N.Word(reflected),doubled).Store();m.Word(particle+0x14,newVelocity);uint newProduct=N.Mul(N.Word(newVelocity),N.Word(m.Word(node+0x18))).Store();uint newY=N.Sub(N.Word(m.Word(particle+4)),N.Sub(N.Word(newProduct),N.Word(oldProduct))).Store();m.Word(particle+4,newY);uint displacement=N.Sub(N.Word(newY),N.Word(m.Word(node+0x24))).Store(),first,second;uint ok=PtlQuadraticRoots.Values(m.Word(record+0xa0),m.Word(particle+0x14),displacement,out first,out second);if(ok!=0){uint maximum=F(first)>F(second)?first:second;if(F(maximum)<F(m.Word(record+0xa4))){uint delta=N.Sub(N.Word(maximum),N.Word(m.Word(node+0x18))).Store();m.Word(node+0x18,maximum);if(F(delta)>F(0x3ca3d70a)){m.Word(node+4,N.Add(N.Word(delta),N.Word(m.Word(node+4))).Store());PtlParticleLinks.Timed(m,node,head);return;}}}Recycle(m,node);}}public static void Plane(SoundSetupImage m,uint node){unchecked{uint particle=m.Word(node)+(m.Word(node+0x14)+1)*32;uint[] normal=Normal(m,unchecked((short)m.Half(node+0x20)));uint dot=N.Add(N.Mul(N.Word(m.Word(particle+0x18)),N.Word(normal[2])),N.Mul(N.Word(m.Word(particle+0x10)),N.Word(normal[0]))).Store();uint impulse=N.Neg(N.Mul(N.Word(dot),N.Add(N.Word(m.Word(node+0x28)),N.Integer(1)))).Store();uint oldX=N.Mul(N.Word(m.Word(particle+0x10)),N.Word(m.Word(node+0x18))).Store(),oldZ=N.Mul(N.Word(m.Word(particle+0x18)),N.Word(m.Word(node+0x18))).Store();uint vx=N.Add(N.Word(m.Word(particle+0x10)),N.Mul(N.Word(impulse),N.Word(normal[0]))).Store();m.Word(particle+0x10,vx);uint vz=N.Add(N.Mul(N.Word(impulse),N.Word(normal[2])),N.Word(m.Word(particle+0x18))).Store();m.Word(particle+0x18,vz);uint newZ=N.Mul(N.Word(vz),N.Word(m.Word(node+0x18))).Store(),newX=N.Mul(N.Word(m.Word(particle+0x10)),N.Word(m.Word(node+0x18))).Store();m.Word(particle,N.Sub(N.Word(m.Word(particle)),N.Sub(N.Word(newX),N.Word(oldX))).Store());m.Word(particle+8,N.Sub(N.Word(m.Word(particle+8)),N.Sub(N.Word(newZ),N.Word(oldZ))).Store());Recycle(m,node);}}public static void Process(SoundSetupImage m,int bank){PtlAttachmentRetirement.Process(m,bank,delegate(SoundSetupImage image,uint node,uint head){if(image.Word(node+8)==5)Quadratic(image,node,head);else if(image.Word(node+8)==6)Plane(image,node);else throw new ArgumentException("Unexpected remaining branch.");});}}}
